-- LOCAL DESIGN ONLY; never applied to Supabase by this project.

-- Private schema; do not add to exposed schemas. Preserve source JSON text too.

CREATE SCHEMA IF NOT EXISTS mrt_collector;

SET search_path TO mrt_collector;

BEGIN;

CREATE TABLE IF NOT EXISTS "affiliate_companies" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "code" TEXT NOT NULL,
 "name" TEXT NOT NULL,
 "integration_type" TEXT NOT NULL DEFAULT 'API',
 "api_base_url" TEXT,
 "is_active" BIGINT NOT NULL DEFAULT 1,
 PRIMARY KEY ("id"),
 UNIQUE ("code")
);

CREATE TABLE IF NOT EXISTS "api_probe_runs" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "endpoint" TEXT NOT NULL,
 "keyword" TEXT,
 "city" TEXT,
 "status_code" BIGINT NOT NULL,
 "elapsed_ms" BIGINT,
 "result_count" BIGINT,
 "collection_path" TEXT,
 "fields_json" JSONB,
 "fields_json_text" TEXT,
 "response_path" TEXT,
 "recorded_at" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "collection_jobs" (
 "job_key" TEXT NOT NULL,
 "job_json" JSONB NOT NULL,
 "job_json_text" TEXT,
 "next_page" BIGINT NOT NULL,
 "status" TEXT NOT NULL,
 "last_error" TEXT,
 "total_count" BIGINT,
 "pages_done" BIGINT NOT NULL DEFAULT 0,
 "fetched_items" BIGINT NOT NULL DEFAULT 0,
 "updated_at" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("job_key")
);

CREATE TABLE IF NOT EXISTS "collection_overlap_events" (
 "job_key" TEXT NOT NULL,
 "requested_page" BIGINT NOT NULL,
 "product_id" TEXT NOT NULL,
 "first_page" BIGINT NOT NULL,
 "detected_at" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("job_key","requested_page","product_id")
);

CREATE TABLE IF NOT EXISTS "collector_migrations" (
 "version" BIGINT NOT NULL,
 "applied_at" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("version")
);

CREATE TABLE IF NOT EXISTS "collector_runs" (
 "run_id" TEXT NOT NULL,
 "command" TEXT NOT NULL,
 "started_at" TIMESTAMPTZ NOT NULL,
 "ended_at" TIMESTAMPTZ,
 "status" TEXT NOT NULL,
 "context_json" JSONB NOT NULL DEFAULT '{}'::jsonb,
 "context_json_text" TEXT,
 PRIMARY KEY ("run_id")
);

CREATE TABLE IF NOT EXISTS "enrichment_details" (
 "product_id" BIGINT NOT NULL,
 "kind" TEXT NOT NULL,
 "source" TEXT NOT NULL,
 "payload_json" JSONB NOT NULL,
 "payload_json_text" TEXT,
 "fetched_at" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("product_id","kind")
);

CREATE TABLE IF NOT EXISTS "enrichment_runs" (
 "product_id" BIGINT NOT NULL,
 "kind" TEXT NOT NULL,
 "status" TEXT NOT NULL DEFAULT 'PENDING',
 "attempts" BIGINT NOT NULL DEFAULT 0,
 "requested_at" TIMESTAMPTZ,
 "updated_at" TIMESTAMPTZ NOT NULL,
 "response_path" TEXT,
 "error" TEXT,
 PRIMARY KEY ("product_id","kind")
);

CREATE TABLE IF NOT EXISTS "nationwide_jobs" (
 "job_id" TEXT NOT NULL,
 "phase" TEXT NOT NULL,
 "region_json" JSONB NOT NULL,
 "region_json_text" TEXT,
 "keyword" TEXT NOT NULL,
 "checkin" TEXT,
 "checkout" TEXT,
 "adults" BIGINT,
 "next_page" BIGINT NOT NULL,
 "status" TEXT NOT NULL,
 "error" TEXT,
 "pages" BIGINT NOT NULL DEFAULT 0,
 "returned" BIGINT NOT NULL DEFAULT 0,
 "unique_seen" BIGINT NOT NULL DEFAULT 0,
 "updated_at" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("job_id")
);

CREATE TABLE IF NOT EXISTS "nationwide_pages" (
 "job_id" TEXT NOT NULL,
 "page" BIGINT NOT NULL,
 "response_path" TEXT,
 "http_status" BIGINT NOT NULL,
 "returned" BIGINT NOT NULL,
 "new_ids" BIGINT NOT NULL,
 "overlap_ids" BIGINT NOT NULL,
 "reported_total" BIGINT,
 "has_next" TEXT,
 "fetched_at" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("job_id","page")
);

CREATE TABLE IF NOT EXISTS "nationwide_product_observations" (
 "phase" TEXT NOT NULL,
 "provider_id" TEXT NOT NULL,
 "job_id" TEXT NOT NULL,
 "source_region_json" JSONB NOT NULL,
 "source_region_json_text" TEXT,
 "query_keyword" TEXT NOT NULL,
 "observed_at" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("phase","provider_id","job_id")
);

CREATE TABLE IF NOT EXISTS "nationwide_seen" (
 "job_id" TEXT NOT NULL,
 "provider_id" TEXT NOT NULL,
 PRIMARY KEY ("job_id","provider_id")
);

CREATE TABLE IF NOT EXISTS "stay44_observations" (
 "session_id" TEXT NOT NULL,
 "job_key" TEXT NOT NULL,
 "keyword" TEXT NOT NULL,
 "checkin" TEXT NOT NULL,
 "checkout" TEXT NOT NULL,
 "adults" BIGINT NOT NULL,
 "round_number" BIGINT NOT NULL,
 "requested_page" BIGINT NOT NULL,
 "requested_at" TIMESTAMPTZ NOT NULL,
 "status_code" BIGINT NOT NULL,
 "reported_total" BIGINT,
 "returned_page" BIGINT,
 "ids_json" JSONB NOT NULL,
 "ids_json_text" TEXT,
 "raw_response_path" TEXT,
 "count" BIGINT NOT NULL,
 "new_in_job" BIGINT NOT NULL,
 "overlap_in_job" BIGINT NOT NULL,
 "same_page_jaccard" DOUBLE PRECISION,
 "error" TEXT,
 PRIMARY KEY ("session_id","job_key","round_number","requested_page")
);

CREATE TABLE IF NOT EXISTS "stay44_sessions" (
 "session_id" TEXT NOT NULL,
 "started_at" TIMESTAMPTZ NOT NULL,
 "ended_at" TIMESTAMPTZ,
 "status" TEXT NOT NULL,
 "jobs_count" BIGINT NOT NULL,
 "calls" BIGINT NOT NULL DEFAULT 0,
 "note" TEXT NOT NULL DEFAULT 'OBSERVED_ONLY_NOT_EXHAUSTIVE',
 PRIMARY KEY ("session_id")
);

CREATE TABLE IF NOT EXISTS "affiliate_products" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "affiliate_company_id" BIGINT NOT NULL,
 "provider_product_id" TEXT NOT NULL,
 "product_type" TEXT NOT NULL,
 "title" TEXT,
 "product_url" TEXT,
 "source_keyword" TEXT,
 "source_city" TEXT,
 "first_seen_at" TIMESTAMPTZ NOT NULL,
 "last_seen_at" TIMESTAMPTZ NOT NULL,
 "raw_json" JSONB NOT NULL,
 "raw_json_text" TEXT,
 PRIMARY KEY ("id"),
 UNIQUE ("affiliate_company_id","provider_product_id","product_type"),
 FOREIGN KEY ("affiliate_company_id") REFERENCES "affiliate_companies" ("id")
);

CREATE TABLE IF NOT EXISTS "collection_pages" (
 "job_key" TEXT NOT NULL,
 "requested_page" BIGINT NOT NULL,
 "returned_page" BIGINT,
 "http_status" BIGINT NOT NULL,
 "item_count" BIGINT NOT NULL,
 "distinct_item_count" BIGINT NOT NULL,
 "total_count" BIGINT,
 "overlapping_ids" BIGINT NOT NULL,
 "response_file" TEXT,
 "fetched_at" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("job_key","requested_page"),
 FOREIGN KEY ("job_key") REFERENCES "collection_jobs" ("job_key")
);

CREATE TABLE IF NOT EXISTS "collection_seen_ids" (
 "job_key" TEXT NOT NULL,
 "product_id" TEXT NOT NULL,
 "first_page" BIGINT NOT NULL,
 PRIMARY KEY ("job_key","product_id"),
 FOREIGN KEY ("job_key") REFERENCES "collection_jobs" ("job_key")
);

CREATE TABLE IF NOT EXISTS "affiliate_links" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "affiliate_company_id" BIGINT NOT NULL,
 "affiliate_product_id" BIGINT,
 "target_url" TEXT NOT NULL,
 "affiliate_url" TEXT NOT NULL,
 "placement" TEXT NOT NULL DEFAULT 'default',
 "created_at" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("id"),
 UNIQUE ("affiliate_company_id","target_url","placement"),
 FOREIGN KEY ("affiliate_product_id") REFERENCES "affiliate_products" ("id"),
 FOREIGN KEY ("affiliate_company_id") REFERENCES "affiliate_companies" ("id")
);

CREATE TABLE IF NOT EXISTS "product_observations" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "event_key" TEXT NOT NULL,
 "product_id" BIGINT,
 "kind" TEXT NOT NULL,
 "source" TEXT NOT NULL,
 "observed_at" TIMESTAMPTZ,
 "request_json" JSONB NOT NULL DEFAULT '{}'::jsonb,
 "request_json_text" TEXT,
 "payload_json" JSONB NOT NULL,
 "payload_json_text" TEXT,
 "response_path" TEXT,
 "http_status" BIGINT,
 "status" TEXT NOT NULL,
 "error" TEXT,
 "run_id" TEXT,
 "imported_at" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("id"),
 UNIQUE ("event_key"),
 FOREIGN KEY ("run_id") REFERENCES "collector_runs" ("run_id"),
 FOREIGN KEY ("product_id") REFERENCES "affiliate_products" ("id")
);

CREATE TABLE IF NOT EXISTS "product_locations" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "observation_id" BIGINT NOT NULL,
 "product_id" BIGINT NOT NULL,
 "json_path" TEXT NOT NULL,
 "place_name" TEXT,
 "country" TEXT,
 "city" TEXT,
 "address" TEXT,
 "latitude_json" JSONB,
 "latitude_json_text" TEXT,
 "longitude_json" JSONB,
 "longitude_json_text" TEXT,
 "source" TEXT NOT NULL,
 "verification_status" TEXT NOT NULL DEFAULT 'PROVIDER_REPORTED',
 "payload_json" JSONB NOT NULL,
 "payload_json_text" TEXT,
 PRIMARY KEY ("id"),
 UNIQUE ("observation_id","json_path"),
 FOREIGN KEY ("product_id") REFERENCES "affiliate_products" ("id"),
 FOREIGN KEY ("observation_id") REFERENCES "product_observations" ("id")
);

CREATE TABLE IF NOT EXISTS "product_prices" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "observation_id" BIGINT NOT NULL,
 "product_id" BIGINT NOT NULL,
 "json_path" TEXT NOT NULL,
 "value_json" JSONB NOT NULL,
 "value_json_text" TEXT,
 "currency" TEXT,
 "observed_at" TIMESTAMPTZ,
 "request_json" JSONB NOT NULL,
 "request_json_text" TEXT,
 "source" TEXT NOT NULL,
 PRIMARY KEY ("id"),
 UNIQUE ("observation_id","json_path"),
 FOREIGN KEY ("product_id") REFERENCES "affiliate_products" ("id"),
 FOREIGN KEY ("observation_id") REFERENCES "product_observations" ("id")
);

CREATE INDEX IF NOT EXISTS "idx_enrichment_status" ON "enrichment_runs" ("kind","status");

CREATE INDEX IF NOT EXISTS "locations_product" ON "product_locations" ("product_id");

CREATE INDEX IF NOT EXISTS "observations_run" ON "product_observations" ("run_id");

CREATE INDEX IF NOT EXISTS "observations_product_kind" ON "product_observations" ("product_id","kind","observed_at");

CREATE INDEX IF NOT EXISTS "prices_product_time" ON "product_prices" ("product_id","observed_at");

CREATE INDEX IF NOT EXISTS "stay44_obs_job" ON "stay44_observations" ("job_key","requested_page","requested_at");

CREATE OR REPLACE VIEW collector_link_state WITH (security_invoker=true) AS
 SELECT p.id AS product_id,
 EXISTS(SELECT 1 FROM affiliate_links l WHERE l.affiliate_company_id=p.affiliate_company_id
 AND l.target_url=p.product_url AND (l.affiliate_product_id=p.id OR l.affiliate_product_id IS NULL)) AS has_link,
 COALESCE(o.status,r.status) AS last_attempt_status,
 CASE WHEN o.id IS NOT NULL THEN o.error ELSE r.error END AS last_attempt_error,
 COALESCE(o.observed_at,r.updated_at) AS last_attempt_at
 FROM affiliate_products p
 LEFT JOIN enrichment_runs r ON r.product_id=p.id AND r.kind='link'
 LEFT JOIN product_observations o ON o.id=(SELECT a.id FROM product_observations a
 WHERE a.product_id=p.id AND a.kind='link' AND a.source!='existing_link'
 ORDER BY a.observed_at DESC,a.id DESC LIMIT 1);

COMMIT;
